-- A workspace database written by the build before stage 5 (commit 0bc9d34,
-- schema v6) with the public fixture key of journal_data.dart (bytes 19).
-- Fixture values only. Besides servers, documents, an unmaterialized client
-- edit and a publication result, it holds leftovers of the exchange removed
-- on 2026-09-24: outbox, packets, the sync key, an unresolved conflict, an
-- extra branch and a waiting received change.
BEGIN TRANSACTION;
CREATE TABLE documents (id TEXT PRIMARY KEY, payload BLOB NOT NULL, revision INTEGER NOT NULL CHECK(revision > 0));
CREATE TABLE migrations (id TEXT PRIMARY KEY);
CREATE TABLE servers (id TEXT PRIMARY KEY, payload BLOB NOT NULL, revision INTEGER NOT NULL CHECK(revision > 0), updated_at INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE sync_branches (entity_kind TEXT NOT NULL, entity_id TEXT NOT NULL, change_id TEXT NOT NULL, PRIMARY KEY(entity_kind,entity_id,change_id));
CREATE TABLE sync_changes (change_id TEXT PRIMARY KEY, sequence INTEGER NOT NULL UNIQUE CHECK(sequence>0), header TEXT NOT NULL, payload BLOB NOT NULL);
CREATE TABLE sync_conflicts (entity_kind TEXT NOT NULL, entity_id TEXT NOT NULL, PRIMARY KEY(entity_kind,entity_id));
CREATE TABLE "sync_heads" (entity_kind TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), change_id TEXT NOT NULL, deleted INTEGER NOT NULL CHECK(deleted IN (0,1)), PRIMARY KEY(entity_kind,entity_id));
CREATE TABLE sync_identity (singleton INTEGER PRIMARY KEY CHECK(singleton=1), workspace_id TEXT NOT NULL, device_id TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>=0), proof BLOB NOT NULL, write_guard INTEGER NOT NULL DEFAULT 0 CHECK(write_guard IN (0,1)), writer_device TEXT, writer_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sync_incoming (change_id TEXT PRIMARY KEY, header TEXT NOT NULL, payload BLOB NOT NULL, state INTEGER NOT NULL CHECK(state IN (0,1,2,3)));
CREATE TABLE sync_keys (singleton INTEGER PRIMARY KEY CHECK(singleton=1), payload BLOB NOT NULL);
CREATE TABLE sync_merge_meta (singleton INTEGER PRIMARY KEY CHECK(singleton=1), epoch INTEGER NOT NULL);
CREATE TABLE sync_outbox (change_id TEXT PRIMARY KEY REFERENCES sync_changes(change_id));
CREATE TABLE sync_packets (change_id TEXT PRIMARY KEY REFERENCES sync_changes(change_id), payload BLOB NOT NULL);
CREATE TABLE vpn_overlay_state (singleton INTEGER PRIMARY KEY CHECK(singleton=1), base_revision INTEGER NOT NULL CHECK(base_revision>0), revision INTEGER NOT NULL CHECK(revision>base_revision));
CREATE TABLE vpn_profile_overlay (user_id TEXT PRIMARY KEY, payload BLOB NOT NULL, revision INTEGER NOT NULL CHECK(revision>0));
CREATE TABLE vpn_user_overlay (user_id TEXT PRIMARY KEY, payload BLOB NOT NULL, revision INTEGER NOT NULL CHECK(revision>0));
CREATE TRIGGER sync_changes_immutable_update BEFORE UPDATE ON sync_changes BEGIN SELECT RAISE(ABORT, 'immutable_change'); END;
CREATE TRIGGER sync_changes_immutable_delete BEFORE DELETE ON sync_changes BEGIN SELECT RAISE(ABORT, 'immutable_change'); END;
CREATE TRIGGER sync_incoming_immutable BEFORE UPDATE OF change_id,header,payload ON sync_incoming BEGIN SELECT RAISE(ABORT, 'immutable_change'); END;
CREATE TRIGGER journal_guard_servers_insert BEFORE insert ON servers WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_servers_update BEFORE update ON servers WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_servers_delete BEFORE delete ON servers WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_documents_insert BEFORE insert ON documents WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_documents_update BEFORE update ON documents WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_documents_delete BEFORE delete ON documents WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_overlay_state_insert BEFORE insert ON vpn_overlay_state WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_overlay_state_update BEFORE update ON vpn_overlay_state WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_overlay_state_delete BEFORE delete ON vpn_overlay_state WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_user_overlay_insert BEFORE insert ON vpn_user_overlay WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_user_overlay_update BEFORE update ON vpn_user_overlay WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_user_overlay_delete BEFORE delete ON vpn_user_overlay WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_profile_overlay_insert BEFORE insert ON vpn_profile_overlay WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_profile_overlay_update BEFORE update ON vpn_profile_overlay WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
CREATE TRIGGER journal_guard_vpn_profile_overlay_delete BEFORE delete ON vpn_profile_overlay WHEN (SELECT write_guard != 1 OR writer_device IS NOT device_id OR writer_version != 6 FROM sync_identity WHERE singleton=1) BEGIN SELECT RAISE(ABORT, 'journal_writer_required'); END;
COMMIT;
PRAGMA user_version=6;
